{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    required = case.get("required_symbols", [])
    by_id = {node["id"]: node for node in nodes}
    retained = {node["id"] for node in nodes if not node.get("removable", False)}

    for symbol in required:
        candidates = [node for node in nodes if node.get("symbol") == symbol]
        if candidates:
            best = max(candidates, key=lambda node: node.get("utility", 0))
            retained.add(best["id"])

    pending = list(retained)
    while pending:
        node_id = pending.pop()
        node = by_id.get(node_id)
        if node is None:
            continue
        parent = node.get("parent")
        if parent is not None and parent not in retained and parent in by_id:
            retained.add(parent)
            pending.append(parent)

    removed_node_ids = []
    retained_node_ids = []
    for node in nodes:
        node_id = node["id"]
        if node_id in retained:
            retained_node_ids.append(node_id)
        else:
            removed_node_ids.append(node_id)

    return {
        "removed_node_ids": removed_node_ids,
        "retained_node_ids": retained_node_ids,
    }
"}
